#!/usr/bin/env python3
"""Export Codex-selected canonical object frames for FLUX and reconstruction."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any

import cv2
import numpy as np

from pipeline.utils import parse_worker_args


def parse_args() -> argparse.Namespace:
    """Parse the worker job generated by the pipeline orchestrator."""

    parser = argparse.ArgumentParser()
    parser.add_argument("--reasoning", type=Path, required=True)
    parser.add_argument("--global-masks", type=Path, required=True)
    parser.add_argument("--source-video", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--crop-size", type=int, default=768)
    parser.add_argument("--crop-context", type=float, default=3.0)
    parser.add_argument("--schema-version", required=True)
    parser.add_argument(
        "--registry-key",
        choices=("objects", "support_objects"),
        default="objects",
    )
    return parse_worker_args(parser)


def read_video_frame(path: Path, frame_index: int) -> np.ndarray:
    """Read one source frame without changing its aspect ratio."""

    capture = cv2.VideoCapture(str(path))
    if not capture.isOpened():
        raise OSError(path)
    try:
        capture.set(cv2.CAP_PROP_POS_FRAMES, frame_index)
        ok, frame = capture.read()
    finally:
        capture.release()
    if not ok:
        raise OSError(f"Cannot read frame {frame_index} from {path}")
    return frame


def unpack_mask(path: Path, source_frame: int) -> tuple[np.ndarray, float]:
    """Load the consolidated mask at a requested source frame."""

    archive = np.load(path)
    source_indices = np.asarray(archive["source_indices"], dtype=np.int32)
    locations = np.flatnonzero(source_indices == source_frame)
    if not len(locations):
        raise ValueError(f"Mask archive has no source frame {source_frame}")
    index = int(locations[0])
    width = int(archive["mask_width"])
    packed = np.asarray(archive["packed_masks"])[index]
    mask = np.unpackbits(packed, axis=1)[:, :width].astype(bool)
    score = float(np.asarray(archive["scores"])[index])
    if not mask.any():
        raise ValueError(f"Canonical frame {source_frame} has no tracked object mask")
    return mask, score


def bounds(mask: np.ndarray) -> list[int]:
    """Return a half-open xyxy mask bounding box."""

    ys, xs = np.nonzero(mask)
    if not len(xs):
        raise ValueError("Empty mask")
    return [int(xs.min()), int(ys.min()), int(xs.max()) + 1, int(ys.max()) + 1]


def crop_square(
    frame: np.ndarray,
    mask: np.ndarray,
    bbox_xyxy: list[int],
    *,
    context: float,
    output_side: int,
) -> tuple[np.ndarray, np.ndarray, dict[str, Any]]:
    """Crop with isotropic neutral-gray padding, avoiding stretch or mirroring."""

    height, width = mask.shape
    mask_box = bounds(mask)
    x0 = min(int(bbox_xyxy[0]), mask_box[0])
    y0 = min(int(bbox_xyxy[1]), mask_box[1])
    x1 = max(int(bbox_xyxy[2]), mask_box[2])
    y1 = max(int(bbox_xyxy[3]), mask_box[3])
    center_x, center_y = (x0 + x1) / 2.0, (y0 + y1) / 2.0
    requested_side = max(64.0, max(x1 - x0, y1 - y0) * context)
    requested_side = min(requested_side, float(max(width, height)))
    left = int(round(center_x - requested_side / 2.0))
    top = int(round(center_y - requested_side / 2.0))
    right = int(round(center_x + requested_side / 2.0))
    bottom = int(round(center_y + requested_side / 2.0))
    clipped_left, clipped_top = max(0, left), max(0, top)
    clipped_right, clipped_bottom = min(width, right), min(height, bottom)
    crop = frame[clipped_top:clipped_bottom, clipped_left:clipped_right]
    crop_mask = mask[clipped_top:clipped_bottom, clipped_left:clipped_right].astype(np.uint8) * 255
    pad_left = clipped_left - left
    pad_top = clipped_top - top
    pad_right = right - clipped_right
    pad_bottom = bottom - clipped_bottom
    side = max(crop.shape[:2])
    pad_right += side - (crop.shape[1] + pad_left + pad_right)
    pad_bottom += side - (crop.shape[0] + pad_top + pad_bottom)
    pad_left, pad_top, pad_right, pad_bottom = (
        max(0, int(value)) for value in (pad_left, pad_top, pad_right, pad_bottom)
    )
    crop = cv2.copyMakeBorder(
        crop,
        pad_top,
        pad_bottom,
        pad_left,
        pad_right,
        cv2.BORDER_CONSTANT,
        value=(127, 127, 127),
    )
    crop_mask = cv2.copyMakeBorder(
        crop_mask,
        pad_top,
        pad_bottom,
        pad_left,
        pad_right,
        cv2.BORDER_CONSTANT,
        value=0,
    )
    # Rounding and asymmetric clipping can leave one dimension one pixel short.
    square_side = max(crop.shape[:2])
    if crop.shape[:2] != (square_side, square_side):
        crop = cv2.copyMakeBorder(
            crop,
            0,
            square_side - crop.shape[0],
            0,
            square_side - crop.shape[1],
            cv2.BORDER_CONSTANT,
            value=(127, 127, 127),
        )
        crop_mask = cv2.copyMakeBorder(
            crop_mask, 0, square_side - crop_mask.shape[0], 0, square_side - crop_mask.shape[1], cv2.BORDER_CONSTANT, value=0
        )
    resized = cv2.resize(crop, (output_side, output_side), interpolation=cv2.INTER_LANCZOS4)
    resized_mask = cv2.resize(
        crop_mask, (output_side, output_side), interpolation=cv2.INTER_NEAREST
    )
    return resized, resized_mask, {
        "source_crop_xyxy": [clipped_left, clipped_top, clipped_right, clipped_bottom],
        "source_crop_size": [clipped_right - clipped_left, clipped_bottom - clipped_top],
        "square_padding_ltrb": [pad_left, pad_top, pad_right, pad_bottom],
        "output_size": [output_side, output_side],
        "scale_x": output_side / square_side,
        "scale_y": output_side / square_side,
    }


def run_reference_export(args: argparse.Namespace) -> None:
    """Export exactly one primary reference per Codex physical object."""

    reasoning_path = args.reasoning.expanduser().resolve()
    mask_dir = args.global_masks.expanduser().resolve()
    video = args.source_video.expanduser().resolve()
    output = args.output_dir.expanduser().resolve()
    output.mkdir(parents=True, exist_ok=True)
    reasoning = json.loads(reasoning_path.read_text(encoding="utf-8"))
    mask_manifest = json.loads((mask_dir / "manifest.json").read_text(encoding="utf-8"))
    mask_by_id = {
        str(item["global_object_id"]): Path(item["mask_file"])
        for item in mask_manifest["objects"]
    }
    summaries = []
    registry = reasoning.get(args.registry_key)
    if not isinstance(registry, list):
        raise ValueError(f"Reasoning has no {args.registry_key!r} registry")
    for object_record in registry:
        object_id = str(object_record["global_object_id"])
        if object_id not in mask_by_id:
            raise FileNotFoundError(f"No consolidated SAM3 mask for {object_id}")
        canonical = object_record["canonical"]
        source_frame = int(canonical["frame"])
        frame = read_video_frame(video, source_frame)
        mask, score = unpack_mask(mask_by_id[object_id], source_frame)
        if mask.shape != frame.shape[:2]:
            mask = cv2.resize(
                mask.astype(np.uint8),
                (frame.shape[1], frame.shape[0]),
                interpolation=cv2.INTER_NEAREST,
            ).astype(bool)
        crop, crop_mask, transform = crop_square(
            frame,
            mask,
            [int(value) for value in canonical["bbox_xyxy"]],
            context=float(args.crop_context),
            output_side=int(args.crop_size),
        )
        role_dir = output / object_id / "primary"
        role_dir.mkdir(parents=True, exist_ok=True)
        image_path = role_dir / "reference_rgb.png"
        mask_path = role_dir / "reference_mask.png"
        overlay_path = role_dir / "reference_overlay.png"
        if not cv2.imwrite(str(image_path), crop):
            raise OSError(image_path)
        if not cv2.imwrite(str(mask_path), crop_mask):
            raise OSError(mask_path)
        overlay = crop.copy()
        visible = crop_mask > 0
        overlay[visible] = (
            0.55 * overlay[visible] + 0.45 * np.asarray([80, 220, 40], dtype=np.uint8)
        ).astype(np.uint8)
        cv2.imwrite(str(overlay_path), overlay)
        selected = {
            "role": "primary",
            "source_frame": source_frame,
            "image_path": str(image_path.resolve()),
            "mask_path": str(mask_path.resolve()),
            "crop_transform": transform,
            "metrics": {
                "sam_score": score,
                "mask_pixels": int(mask.sum()),
                "codex_bbox_xyxy": canonical["bbox_xyxy"],
                "tracked_mask_bbox_xyxy": bounds(mask),
            },
        }
        record = {
            "schema_version": args.schema_version,
            "global_object_id": object_id,
            "object_name": object_record["name"],
            "observed_object_names": [object_record["name"]],
            "selection_policy": {
                "source": "Codex global canonical frame",
                "ranking_source": "codex_whole_video_reasoning",
                "fallbacks": 0,
            },
            "selected": [selected],
        }
        (output / object_id / "selection.json").write_text(
            json.dumps(record, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
        summaries.append(
            {
                "global_object_id": object_id,
                "object_name": object_record["name"],
                "ranking_source": "codex_whole_video_reasoning",
                "selected": [{"role": "primary", "source_frame": source_frame}],
            }
        )
        print(json.dumps(summaries[-1]), flush=True)
    result = output / "reference_frames.json"
    result.write_text(
        json.dumps(
            {
                "schema_version": args.schema_version,
                "reasoning_source": str(reasoning_path),
                "registry_key": args.registry_key,
                "objects": summaries,
            },
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    print(result)


class ObjectReferenceExporter:
    """Worker-facing canonical reference exporter."""

    def __init__(self, arguments: argparse.Namespace) -> None:
        self.arguments = arguments

    @classmethod
    def from_worker_job(cls) -> "ObjectReferenceExporter":
        return cls(parse_args())

    def run(self) -> None:
        run_reference_export(self.arguments)


def main() -> None:
    ObjectReferenceExporter.from_worker_job().run()


if __name__ == "__main__":
    main()
